#!/bin/bash

Rscript -e 'install.packages("BiocManager", repos = "http://cran.us.r-project.org")'
Rscript -e 'BiocManager::install("edgeR")'

#indexing hisat2
hisat2-build /home/shared_folder/genome_files/Homo_sapiens.GRCh38.dna_sm.primary_assembly.fa /home/shared_folder/GRCh38.113

#input CIRIquant
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-Input1-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-Input1-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p WT_Input1 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_WT_Input1 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-Input2-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-Input2-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p WT_Input2 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_WT_Input2 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-Input3-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-Input3-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p WT_Input3 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_WT_Input3 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-Input4-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-Input4-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p WT_Input4 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_WT_Input4 --tool CIRI2

CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-Input1-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-Input1-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p KO_Input1 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_KO_Input1 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-Input2-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-Input2-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p KO_Input2 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_KO_Input2 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-Input3-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-Input3-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p KO_Input3 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_KO_Input3 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-Input4-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-Input4-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_input/quant -p KO_Input4 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_input/CIRI2_input/ciri2_KO_Input4 --tool CIRI2

prep_CIRIquant -i /home/shared_folder/circRNAs_input/dge_WT_RBM20KO_input.txt --lib /home/shared_folder/circRNAs_input/WT_RBM20KO_library_input.csv --circ /home/shared_folder/circRNAs_input/WT_RBM20KO_circ_anno_input.csv --bsj /home/shared_folder/circRNAs_input/WT_RBM20KO_circ_exp_input.csv --ratio /home/shared_folder/circRNAs_input/WT_RBM20KO_circ_ratio_input.csv

#pulldown CIRIquant
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-pulldown1-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-pulldown1-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p WT_pulldown1 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_WT_pulldown1 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-pulldown2-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-pulldown2-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p WT_pulldown2 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_WT_pulldown2 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-pulldown3-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-pulldown3-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p WT_pulldown3 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_WT_pulldown3 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/TTN-pulldown4-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/TTN-pulldown4-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p WT_pulldown4 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_WT_pulldown4 --tool CIRI2

CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-pulldown1-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-pulldown1-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p KO_pulldown1 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_KO_pulldown1 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-pulldown2-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-pulldown2-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p KO_pulldown2 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_KO_pulldown2 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-pulldown3-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-pulldown3-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p KO_pulldown3 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_KO_pulldown3 --tool CIRI2
CIRIquant --config /home/shared_folder/environment.yml -1 /home/shared_folder/fastq/KO-pulldown4-RNA_R1_001.fastq.gz -2 /home/shared_folder/fastq/KO-pulldown4-RNA_R2_001.fastq.gz -o /home/shared_folder/circRNAs_pulldown/quant -p KO_pulldown4 -t 20 --library-type 2 --circ /home/shared_folder/circRNAs_pulldown/CIRI2_pulldown/ciri2_KO_pulldown4 --tool CIRI2

prep_CIRIquant -i /home/shared_folder/circRNAs_pulldown/dge_WT_RBM20KO_pulldown.txt --lib /home/shared_folder/circRNAs_pulldown/WT_RBM20KO_library_pulldown.csv --circ /home/shared_folder/circRNAs_pulldown/WT_RBM20KO_circ_anno_pulldown.csv --bsj /home/shared_folder/circRNAs_pulldown/WT_RBM20KO_circ_exp_pulldown.csv --ratio /home/shared_folder/circRNAs_pulldown/WT_RBM20KO_circ_ratio_pulldown.csv
